"use client";

import { ButtonHTMLAttributes, ReactNode } from "react";

// ─── NeonBlade UI — CornerCutButton Stub ──────────────────────────────────────
// Replace this stub with the real component generated by:
//   npx neonblade add corner-cut-button

interface CornerCutButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  children: ReactNode;
  variant?: "primary" | "outline" | "muted";
  color?: "cyan" | "red" | "green";
  size?: "sm" | "md" | "lg";
}

const CLIP = "polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px))";

export function CornerCutButton({
  children,
  variant = "primary",
  color = "cyan",
  size = "md",
  className = "",
  ...props
}: CornerCutButtonProps) {
  const sizeClasses = {
    sm: "px-4 py-1.5 text-xs",
    md: "px-6 py-2 text-sm",
    lg: "px-8 py-3 text-sm",
  }[size];

  const baseClasses = `
    relative inline-flex items-center justify-center
    font-mono font-bold tracking-[0.2em] uppercase
    transition-all duration-200 cursor-pointer
    focus:outline-none focus-visible:ring-2 focus-visible:ring-cyan-400
    active:scale-95
    ${sizeClasses}
  `;

  const variantClasses = {
    primary: `
      bg-cyan-500 text-black
      hover:bg-cyan-400
      [box-shadow:0_0_18px_rgba(0,255,255,0.5)]
      hover:[box-shadow:0_0_32px_rgba(0,255,255,0.8)]
    `,
    outline: `
      bg-black/30 backdrop-blur-sm
      text-cyan-400
      border border-cyan-500/60
      hover:border-cyan-400 hover:text-cyan-300
      hover:[box-shadow:0_0_16px_rgba(0,255,255,0.3)]
    `,
    muted: `
      bg-white/5 text-cyan-600
      border border-cyan-900/60
      hover:bg-white/10
    `,
  }[variant];

  return (
    <button
      {...props}
      style={{ clipPath: CLIP, ...props.style }}
      className={`${baseClasses} ${variantClasses} ${className}`}
    >
      {children}
    </button>
  );
}
